        }
        guard let data = try? Data(contentsOf: url) else {
            throw ToolError(message: "Wrote \(url.path) but could not read it back.")
        }
        var text =
            "Frame at \(time) ticks of a \(Int(canvasSize.width))×\(Int(canvasSize.height)) px "
            + "canvas, rendered at \(image.width)×\(image.height) px"
        if options.burnInTimecode {
            text += ", with the project timecode burnt in"
        }
        if options.ungraded {
            text += ", with every grade removed"
        }
        if let selection {
            text += ", drawn as clip \(selection)'s qualifier selection (white fully graded, "
                + "black untouched)"
        }
        if output == .hlg, options.dynamicRange == .sdr {
            text += ", as the project's SDR version"
        }
        text += "."
        // Said where the caller can see it rather than only in the schema: a
        // frame off a transparent canvas (phase 7b) has just lost its alpha,
        // and a note that arrives with the file is the one that is read.
        if !format.carriesAlpha {
            text += " " + FrameWriter.flattenNote
        }
        for report in rendered.graphics {
            text += " " + Self.graphicSentence(report)
        }
        // A cursor file the frame could not draw (spec §11 CU-37 (c)).
        for sentence in Exporter.cursorSentences(rendered.cursorWarnings) {
            text += " " + sentence
        }
        if !scopes.isEmpty {
            // The scopes read the frame drawn (spec §11 HD-15 (a), (b)): an HLG
            // project's own picture as HLG, its SDR version (and a JPEG) as SDR.
            let signal = ScopeSignal(output: output, dynamicRange: options.dynamicRange)
            text += " " + (try Self.writeScopes(
                scopes, vectorscopeZoom: vectorscopeZoom, signal: signal, of: image, beside: url))
        }
        // A cut-out clip whose masks were not ready within the wait (spec §11 CO-22 (f)); a
        // picture cut by its foreground names its foreground masks (CO-106).
        let foreground = Set(
            (project.snapshot.clips + project.snapshot.nests.flatMap(\.clips))
                .filter { CutoutWants.kind(of: $0) == .foreground }.map(\.id))
        for sentence in Exporter.cutoutSentences(rendered.uncut, foreground: foreground) {
            text += " " + sentence
        }
        text += " Written to \(url.path)."
        return try callResult(
            content: [
                [
                    "type": "image", "data": data.base64EncodedString(),
                    "mimeType": Self.mimeType(format),
                ],
                ["type": "text", "text": text],
            ], isError: false)
    }

    /// One graphic's report as `render_frame` says it: failed at a frame,
    /// did not compile, or warned — each diagnostic with its location.
    static func graphicSentence(_ report: GraphicReport) -> String {
        let said = report.diagnostics.map { $0.located }.joined(separator: "; ")
        guard let frame = report.frame else {
            return "Graphic \"\(report.name)\" does not compile: \(said)."
        }
        let verb = report.failed ? "failed" : "warned"
        return "Graphic \"\(report.name)\" \(verb) at frame \(frame): \(said)."
    }

    /// Where `render_frame` writes and in what container — its `path` and
    /// `format` arguments resolved together, because neither can be read
    /// without the other.
    ///
    /// **No `path` is the case every proof script takes**, and it is exactly
    /// what it was: a file in the temporary directory named for the tick it
    /// holds, ending in the format's own extension — `.png` unless a caller
    /// asked for something else.
    ///
    /// With a `path`, the format is `FrameWriter`'s answer and not a second
    /// opinion: an explicit `format` wins, else the path's own extension, else
    /// PNG — `export_captions`' rule, one file over. The path then goes
    /// through `destinationURL`, so a wrong extension is REPLACED rather than
    /// appended to: `{path: "shot.jpg", format: "png"}` writes `shot.png`, not
    /// the doubled `shot.jpg.png`, which is why the five image containers
    /// joined `replaceableExtensions` in this phase.
    ///
    /// The folder must already exist and is refused BY NAME when it does not,
    /// which is `export`'s posture at the same point: a tool that created
    /// directories would answer a mistyped path by scattering empty ones.
    private func frameDestination(
        _ a: [String: Any], at time: Ticks
    ) throws -> (url: URL, format: FrameWriter.Format) {
        let requested = try requestedFrameFormat(a)
        guard let given = try stringArg(a, "path") else {
            let format = requested ?? .png
            return (
                Self.temporaryOutput("framejob-frame-\(time)", extension: format.fileExtension),
                format
            )
        }
        let path = try Self.nonEmptyOutputPath(given)
        let format = FrameWriter.format(
            for: URL(fileURLWithPath: (path as NSString).expandingTildeInPath),
            requested: requested)
        let url = try Self.requireFolder(
            of: Self.destinationURL(path, extension: format.fileExtension))
        return (url, format)
    }

    /// The `format` argument, refused BY NAME when it names no container —
    /// nil when it is absent, which is what lets `FrameWriter.format(for:)`
    /// fall back to the path. It is `export_captions`' `requestedFormat` with
    /// three rows instead of two.
    ///
    /// `jpg` is read as `jpeg` on purpose. `FrameWriter.Format`'s raw value is
    /// deliberately NOT its file extension — JPEG has two spellings and
    /// collapsing them would make one of them wrong — and `format(for:)`
    /// already reads both off a path, so refusing four letters here that are
    /// accepted in the argument beside it is an inconsistency a caller meets
    /// on its first try. The schema still advertises the three canonical
    /// names, which is what a caller reading the catalog will send.
    private func requestedFrameFormat(_ a: [String: Any]) throws -> FrameWriter.Format? {
        guard let name = try stringArg(a, "format") else { return nil }
        let lowered = name.lowercased()
        guard let format = FrameWriter.Format(rawValue: lowered == "jpg" ? "jpeg" : lowered)
        else {
            let known = FrameWriter.Format.allCases.map { $0.rawValue }
            throw ToolError(
                message: "format must be one of " + known.joined(separator: ", ")
                    + " (got \"\(name)\").")
        }
        return format
    }

    /// The image block's `mimeType`, read off the format's own `UTType`
    /// rather than switched over a second time here: the block and the file
    /// are then one decision, and a fourth container would arrive described
    /// correctly without anybody remembering this line.
    ///
    /// All three carry one (measured: `image/png`, `image/jpeg`,
    /// `image/heic`). The fallback exists only because the API is optional,
    /// and it is deliberately generic rather than a guess: telling a client
    /// that a HEIC is a PNG is worse than telling it nothing.
    private static func mimeType(_ format: FrameWriter.Format) -> String {
        format.contentType.preferredMIMEType ?? "application/octet-stream"
    }
}

// MARK: - The adjustment pass (spec §11 GR-6)

// An adjustment clip's layer: no texture, one full-frame quad, blending OFF.
// It reads what is already drawn behind it — the target `encodeLayers` is
// drawing into — un-premultiplies it, grades it as step 3's colour adjust
// (`gradeSample`, the chroma key off), steps 4c to 4d's `gradeSteps` and
// step 5's point filters would (the canvas's uv as the filters' local position), and
// premultiplies it back by the destination's own alpha, so alpha is
// preserved. The weight is the layer's opacity, its strength, times the
// matte coverage sampled as step 7c samples it, times the qualifier's `q`
// (spec §11 GR-13), read from the destination BEFORE the grade so the grade
// never moves what it selects — or, with `q.blurred` set, read from the
// blurred map at `texture(0)` the selection pass made from that same
// destination (spec §11 GR-35). With `q.selection` set the pass writes
// `q` × coverage as opaque grey instead (Show Selection); the coverage is
// never blurred. On a linear canvas (spec §11 HD-16 (e)) the destination is
// encoded before the qualifier and the grade read it and the graded colour
// decoded before the strength mix, which stays in linear light like every
// other opacity; Show Selection's grey is decoded, so the frame shows the
// grey it showed before.
fragment float4 framejob_adjust_fragment(ShadowVaryings in [[stage_in]],
                                        constant LayerUniforms &u [[buffer(0)]],
                                        constant QualifierUniforms &q [[buffer(1)]],
                                        float4 dst [[color(0)]],
                                        texture2d<float> selectionMap [[texture(0)]],
                                        texture2d<float> matte [[texture(1)]],
                                        texture3d<float> look [[texture(2)]],
                                        texture2d<float> curves [[texture(3)]],
                                        sampler samp [[sampler(0)]]) {
    float a = saturate(dst.a);
    float3 c = saturate(dst.rgb / max(a, 1e-4));
    bool linear = u.linearLight > 0.5;
    if (linear) {
        c = blendEncode(c, u.hlgOutput);
    }
    float2 local = canvasPixels(in.position.xy, float2(u.canvasPerDestX, u.canvasPerDestY))
        / max(float2(u.canvasWidth, u.canvasHeight), float2(1.0));
    float coverage = matte.sample(samp, local).r;
    float selected = 1.0;
    if (q.enabled > 0.5) {
        selected = q.blurred > 0.5 ? selectionMap.read(uint2(in.position.xy)).r
            : qualifierWeight(c, q);
    }
    if (q.selection > 0.5) {
        float3 grey = float3(saturate(selected * coverage));
        return float4(linear ? blendDecode(grey, u.hlgOutput) : grey, 1.0);
    }
    c = gradeSample(c, 1.0, u).rgb;
    c = gradeSteps(c, u, curves, look, samp);
    for (int i = 0; i < 4; ++i) {
        float2 slot = filterSlot(u, i);
        c = pointFilter(int(slot.x + 0.5), clamp(slot.y, 0.0, 1.0), c, local);
    }
    c = saturate(c);
    if (linear) {
        c = blendDecode(c, u.hlgOutput);
    }
    float4 g = float4(c * a, a);
    float w = saturate(u.opacity * coverage * selected);
    return mix(dst, g, w);
}

// MARK: - The input pass (spec §11 GR-15)

// Step 0: one source frame converted once per frame into a pooled
// `rgba16Float` target the layer stage samples instead (`Compositor+Input
// .swift`). Only the STANDARDS' and the MAKERS' constants live here — the
// BT.2100 HLG inverse OETF's a, b, c; SMPTE ST 2084's m1, m2, c1, c2, c3 (as
// BT.2100 reproduces them); the BT.2020 and BT.709 luminance weights; and the
// camera log curves' constants from Apple's, Sony's and Panasonic's own
    float linearLight;
    float reserved1;
    float reserved2;
};

// 1 at or inside `edge`, falling to 0 across `softness` OUTSIDE it by
// Metal's Hermite `smoothstep`; a hard step at softness 0 (never
// `smoothstep(e, e, x)`, which is undefined).
static inline float qualifierFall(float x, float edge, float softness) {
    if (softness <= 0.0) {
        return x <= edge ? 1.0 : 0.0;
    }
    return 1.0 - smoothstep(edge, edge + softness, x);
}

// A level range: 1 from `low` to `high`, falling outside each edge.
static inline float qualifierLevel(float v, float low, float high, float softness) {
    return qualifierFall(low - v, 0.0, softness) * qualifierFall(v - high, 0.0, softness);
}

// The qualifier's weight `q` of an encoded, saturated, un-premultiplied
// colour (GR-13): HSV hue against the band (wrapping), times the chroma
// guard (no hue below C 0.02, full from 0.06); HSV saturation C / max
// times the near-black guard (dark noise reads unsaturated: 0 at V ≤ 0.03,
// full from 0.10); Y′ on Rec. 709's weights, BT.2020's in an HLG project
// (spec §11 HD-13 (g)). The product of the ranges present, then its
// complement when inverted. S and Y′ are saturated: a fast-math division can
// put C / max an ulp past 1, which a hard edge at 1 would refuse.
static inline float qualifierWeight(float3 c, constant QualifierUniforms &q) {
    float mx = max(c.r, max(c.g, c.b));
    float mn = min(c.r, min(c.g, c.b));
    float chroma = mx - mn;
    float w = 1.0;
    if (q.hueEnabled > 0.5) {
        float hue = hsvHue(c, mx, chroma);
        float d = abs(hue - q.hueCenter);
        d = min(d, 360.0 - d);
        w *= qualifierFall(d, 0.5 * q.hueWidth, q.hueSoftness);
        w *= smoothstep(0.02, 0.06, chroma);
    }
    if (q.satEnabled > 0.5) {
        float s = mx > 0.0 ? saturate(chroma / mx) : 0.0;
        s *= smoothstep(0.03, 0.10, mx);
        w *= qualifierLevel(s, q.satLow, q.satHigh, q.satSoftness);
    }
    if (q.lumaEnabled > 0.5) {
        float y = saturate(dot(c, gradeWeights(q.hlgOutput)));
        w *= qualifierLevel(y, q.lumaLow, q.lumaHigh, q.lumaSoftness);
    }
    return q.invert > 0.5 ? 1.0 - w : w;
}

